def slug(text):
    """Trim edges, lowercase, replace each run of whitespace with one hyphen. Preserve other characters."""
    return text.lower().replace(" ", "-")

def unique(items):
    """Return first occurrence of each item in order; items may be unhashable. Do not mutate input."""
    return list(set(items))

def in_window(value, lower, upper):
    """True for lower <= value < upper. Reject inverted bounds with ValueError; equal bounds form empty window."""
    return lower < value <= upper
